/* USE : UserWebHistMapper.getPauseUserId */
UPDATE  TB_WB_USER_INFO
SET     USER_STAT_FG    =   '50'
,       MOD_ID          =   #{modId}
,       MOD_DT          =   #{modDt}
WHERE   USER_ID         =   #{userId}
AND     USER_STAT_FG    = '00'

/* USE : UserWebHistMapper.getResumeUserId */
UPDATE  TB_WB_USER_INFO
SET     USER_STAT_FG    =   '00'
,       MOD_ID          =   #{modId}
,       MOD_DT          =   #{modDt}
WHERE   USER_ID         =   #{userId}
AND     USER_STAT_FG    = '50'

mapper.select:
/* UserWebHistMapper.getUserWebChkCntList */
WITH P AS ( SELECT #{chkDay1} AS DT_FROM8 , #{chkDay2} AS DT_TO8 , TO_CHAR(SYSDATE - 5 / 1440 , 'YYYYMMDDHH24MISS') AS BEF_5M , TO_CHAR(SYSDATE - 10 / 1440 , 'YYYYMMDDHH24MISS') AS BEF_10M FROM DUAL ) , CHK_RAW AS ( SELECT UPPER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1)) AS USER_KEY , REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1) AS USER_ID , REGEXP_SUBSTR(A.ALARM_MSG, '\| *DATE:([0-9]{8})', 1, 1, NULL, 1) AS CHK_DATE , A.SRC_SYSTEM , A.REG_DT , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *D_TOT:([0-9]+)' , 1, 1, NULL, 1)) AS D_TOT , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *D_EXC:([0-9]+)' , 1, 1, NULL, 1)) AS D_EXC , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *D_REAL:([0-9]+)', 1, 1, NULL, 1)) AS D_REAL , TRIM( REGEXP_SUBSTR(A.ALARM_MSG, '\| *IP:([^|]+)' , 1, 1, NULL, 1)) AS CHK_IP , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *IP_CNT:([0-9]+)', 1, 1, NULL, 1)) AS CHK_IP_CNT , TRIM( REGEXP_SUBSTR(A.ALARM_MSG, '\| *IPS:([^|]+)' , 1, 1, NULL, 1)) AS CHK_IPS , REGEXP_SUBSTR(A.ALARM_MSG, '\| *FIRST:([^|]+)' , 1, 1, NULL, 1) AS FIRST_TS , REGEXP_SUBSTR(A.ALARM_MSG, '\| *LAST:([^|]+)' , 1, 1, NULL, 1) AS LAST_TS FROM TB_MONITOR_ALARM A , P WHERE A.REG_DT BETWEEN P.DT_FROM8 || '000000' AND P.DT_TO8 || '235959' AND A.ALARM_TITLE LIKE '%조회건수%집계%' ) , CHK_TODAY AS ( SELECT R.USER_KEY , MIN(R.USER_ID) AS USER_ID , NVL(SUM(R.D_TOT) , 0) AS TODAY_TOT , NVL(SUM(R.D_EXC) , 0) AS TODAY_EXC , NVL(SUM(R.D_REAL), 0) AS TODAY_REAL , MIN(NVL(R.FIRST_TS, R.LAST_TS)) AS CHK_FIRST_TS , MAX(R.LAST_TS) AS CHK_LAST_TS , MAX(R.REG_DT) AS CHK_LAST_RECV , COUNT(DISTINCT R.SRC_SYSTEM) AS WAS_CNT , MAX(R.CHK_IP) KEEP (DENSE_RANK LAST ORDER BY R.REG_DT) AS CHK_LAST_IP , MAX(R.CHK_IP_CNT) AS CHK_IP_CNT FROM CHK_RAW R , P WHERE R.USER_KEY IS NOT NULL AND R.CHK_DATE BETWEEN P.DT_FROM8 AND P.DT_TO8 GROUP BY R.USER_KEY ) , CHK_5M AS ( SELECT R.USER_KEY , NVL(SUM(R.D_TOT) , 0) AS M5_TOT , NVL(SUM(R.D_EXC) , 0) AS M5_EXC , NVL(SUM(R.D_REAL), 0) AS M5_REAL FROM CHK_RAW R , P WHERE R.USER_KEY IS NOT NULL AND R.REG_DT >= P.BEF_5M GROUP BY R.USER_KEY ) , CHK_5M_IP AS ( SELECT D.USER_KEY , LISTAGG(D.CHK_IPS, ',') WITHIN GROUP (ORDER BY D.CHK_IPS) AS M5_IPS FROM ( SELECT DISTINCT R.USER_KEY, R.CHK_IPS FROM CHK_RAW R , P WHERE R.USER_KEY IS NOT NULL AND R.REG_DT >= P.BEF_5M AND R.CHK_IPS IS NOT NULL AND R.CHK_IPS <> '-' ) D GROUP BY D.USER_KEY ) , BLK_IPSET AS ( SELECT DISTINCT UPPER(B.USER_ID) AS USER_KEY, B.REAL_IP AS IPV FROM TB_WB_LOGIN_HIST_BLOCK B, P WHERE SUBSTR(B.PROC_DT, 1, 8) BETWEEN P.DT_FROM8 AND P.DT_TO8 AND B.REAL_IP IS NOT NULL UNION SELECT DISTINCT UPPER(B.USER_ID), B.LOGIN_IP FROM TB_WB_LOGIN_HIST_BLOCK B, P WHERE SUBSTR(B.PROC_DT, 1, 8) BETWEEN P.DT_FROM8 AND P.DT_TO8 AND B.LOGIN_IP IS NOT NULL ) , CHK_IP_HIT AS ( SELECT DISTINCT C.USER_KEY FROM CHK_TODAY C , BLK_IPSET S WHERE S.USER_KEY = C.USER_KEY AND S.IPV = C.CHK_LAST_IP ) , LOGIN_RAW AS ( SELECT UPPER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1)) AS USER_KEY , REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1) AS USER_ID , REGEXP_SUBSTR(A.ALARM_MSG, '\| *DATE:([0-9]{8})', 1, 1, NULL, 1) AS LGN_DATE , A.SRC_SYSTEM , A.REG_DT , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *TOT:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_TOT , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *SUCC:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_SUCC , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR1:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_E1 , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR2:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_E2 , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR3:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_E3 , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR4:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_E4 , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR5:([0-9]+)' , 1, 1, NULL, 1)) AS LGN_E5 , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *ERR_TOT:([0-9]+)', 1, 1, NULL, 1)) AS LGN_ERR , REGEXP_SUBSTR(A.ALARM_MSG, '\| *FIRST:([^|]+)' , 1, 1, NULL, 1) AS LGN_FIRST_TS , REGEXP_SUBSTR(A.ALARM_MSG, '\| *LAST:([^|]+)' , 1, 1, NULL, 1) AS LGN_LAST_TS FROM TB_MONITOR_ALARM A , P WHERE A.REG_DT BETWEEN P.DT_FROM8 || '000000' AND P.DT_TO8 || '235959' AND A.ALARM_TITLE LIKE '%로그인 시도%집계%' ) , LOGIN_SRC AS ( /* 로그인 알림은 WAS·일자별 당일누적값 → MAX 가 그날 최종값 */ SELECT R.USER_KEY , MIN(R.USER_ID) AS USER_ID , R.SRC_SYSTEM , MAX(R.LGN_TOT) AS TOT_CUM , MAX(R.LGN_SUCC) AS SUCC_CUM , MAX(R.LGN_E1) AS E1_CUM , MAX(R.LGN_E2) AS E2_CUM , MAX(R.LGN_E3) AS E3_CUM , MAX(R.LGN_E4) AS E4_CUM , MAX(R.LGN_E5) AS E5_CUM , MAX(R.LGN_ERR) AS ERR_CUM , MAX(CASE WHEN R.REG_DT < P.BEF_5M THEN R.LGN_TOT END) AS TOT_BASE_5M , MAX(CASE WHEN R.REG_DT < P.BEF_5M THEN R.LGN_SUCC END) AS SUCC_BASE_5M , MAX(CASE WHEN R.REG_DT < P.BEF_5M THEN R.LGN_ERR END) AS ERR_BASE_5M , MIN(NVL(R.LGN_FIRST_TS, R.LGN_LAST_TS)) AS FIRST_TS , MAX(R.LGN_LAST_TS) AS LAST_TS FROM LOGIN_RAW R , P WHERE R.USER_KEY IS NOT NULL AND R.LGN_DATE BETWEEN P.DT_FROM8 AND P.DT_TO8 GROUP BY R.USER_KEY , R.SRC_SYSTEM , R.LGN_DATE ) , LOGIN_TODAY AS ( SELECT S.USER_KEY , MIN(S.USER_ID) AS USER_ID , SUM(S.TOT_CUM) AS LGN_TODAY_TOT , SUM(S.SUCC_CUM) AS LGN_TODAY_SUCC , SUM(NVL(S.E1_CUM, 0)) AS LGN_TODAY_E1 , SUM(NVL(S.E2_CUM, 0)) AS LGN_TODAY_E2 , SUM(NVL(S.E3_CUM, 0)) AS LGN_TODAY_E3 , SUM(NVL(S.E4_CUM, 0)) AS LGN_TODAY_E4 , SUM(NVL(S.E5_CUM, 0)) AS LGN_TODAY_E5 , SUM(S.ERR_CUM) AS LGN_TODAY_ERR , SUM(S.TOT_CUM - NVL(S.TOT_BASE_5M , 0)) AS LGN_5M_TOT , SUM(S.SUCC_CUM - NVL(S.SUCC_BASE_5M, 0)) AS LGN_5M_SUCC , SUM(S.ERR_CUM - NVL(S.ERR_BASE_5M , 0)) AS LGN_5M_ERR , MIN(S.FIRST_TS) AS LGN_FIRST_TS , MAX(S.LAST_TS) AS LGN_LAST_TS FROM LOGIN_SRC S GROUP BY S.USER_KEY ) , LIP_TODAY AS ( /* 로그인 IP수 — 로그인 집계 메시지엔 IP 가 없어 TB_WB_LOGIN_HIST_CHK.LOGIN_IP 기준 */ SELECT UPPER(X.USER_ID) AS USER_KEY , COUNT(DISTINCT X.LOGIN_IP) AS LGN_IP_CNT FROM TB_WB_LOGIN_HIST_CHK X , P WHERE X.PROC_DT BETWEEN P.DT_FROM8 || '000000' AND P.DT_TO8 || '235959999999' AND X.LOGIN_IP IS NOT NULL GROUP BY UPPER(X.USER_ID) ) , ME_RAW AS ( SELECT UPPER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1)) AS USER_KEY , REGEXP_SUBSTR(A.ALARM_MSG, '\| *USER:([^ |]+)' , 1, 1, NULL, 1) AS USER_ID , REGEXP_SUBSTR(A.ALARM_MSG, '\| *DATE:([0-9]{8})' , 1, 1, NULL, 1) AS ME_DATE , NVL( REGEXP_SUBSTR(A.ALARM_MSG, '\| *MIN:([0-9]{12})' , 1, 1, NULL, 1), '-') AS ME_MIN , TRIM( REGEXP_SUBSTR(A.ALARM_MSG, '\| *URL:([^|]+)' , 1, 1, NULL, 1)) AS ME_URL , TO_NUMBER(REGEXP_SUBSTR(A.ALARM_MSG, '\| *CNT:([0-9]+)', 1, 1, NULL, 1)) AS ME_CNT , A.SRC_SYSTEM FROM TB_MONITOR_ALARM A , P WHERE A.REG_DT BETWEEN P.DT_FROM8 || '000000' AND P.DT_TO8 || '235959' AND A.ALARM_TITLE LIKE '%현재메뉴 불일치%' ) , ME_KEY AS ( /* 같은 (WAS·1분구간·아이디·URL) 키는 재전송될수록 CNT 가 커짐 → MAX 가 최종값 */ SELECT R.USER_KEY , MIN(R.USER_ID) AS USER_ID , REGEXP_REPLACE(REGEXP_REPLACE(R.ME_URL, '^[A-Za-z]+://[^/]+', ''), '\?.*$', '') AS NURL , MAX(R.ME_CNT) AS ME_CNT FROM ME_RAW R , P WHERE R.USER_KEY IS NOT NULL AND R.ME_URL IS NOT NULL AND R.ME_DATE BETWEEN P.DT_FROM8 AND P.DT_TO8 GROUP BY R.USER_KEY, R.SRC_SYSTEM, R.ME_DATE, R.ME_MIN , REGEXP_REPLACE(REGEXP_REPLACE(R.ME_URL, '^[A-Za-z]+://[^/]+', ''), '\?.*$', '') ) , ME_TODAY AS ( SELECT K.USER_KEY , MIN(K.USER_ID) AS USER_ID , NVL(SUM(K.ME_CNT), 0) AS ME_TOT , NVL(SUM(CASE WHEN THEN K.ME_CNT ELSE 0 END), 0) AS ME_EXC FROM ME_KEY K GROUP BY K.USER_KEY ) , BLK_TODAY AS ( SELECT UPPER(B.USER_ID) AS USER_KEY , COUNT(*) AS BLK_TODAY_CNT , COUNT(DISTINCT B.REAL_IP) AS BLK_IP_CNT , COUNT(DISTINCT B.COUNTRY_CODE) AS BLK_CC_CNT , MAX(SUBSTR(B.PROC_DT, 1, 14)) AS BLK_LAST_DT , MIN(SUBSTR(B.PROC_DT, 1, 14)) AS BLK_FIRST_DT FROM TB_WB_LOGIN_HIST_BLOCK B , P WHERE SUBSTR(B.PROC_DT, 1, 8) BETWEEN P.DT_FROM8 AND P.DT_TO8 GROUP BY UPPER(B.USER_ID) ) , BLK_10M AS ( SELECT UPPER(B.USER_ID) AS USER_KEY , COUNT(*) AS BLK_10M_CNT FROM TB_WB_LOGIN_HIST_BLOCK B , P WHERE SUBSTR(B.PROC_DT, 1, 14) >= P.BEF_10M GROUP BY UPPER(B.USER_ID) ) , BLK_INFO AS ( SELECT * FROM ( SELECT UPPER(B.USER_ID) AS USER_KEY , B.USER_ID AS BLK_USER_ID , B.STAT_CD , B.LOGIN_ORGN , B.ORGN_CD , B.LOGIN_IP , B.REAL_IP , B.COUNTRY_CODE , B.BLOCK_REASON , B.V_USER_ID , B.USERENV_IP_ADDRESS , SUBSTR(B.BRWSR_INFO, 1, 120) AS BRWSR_INFO , ROW_NUMBER() OVER (PARTITION BY UPPER(B.USER_ID) ORDER BY B.PROC_DT DESC) AS RN FROM TB_WB_LOGIN_HIST_BLOCK B , P WHERE SUBSTR(B.PROC_DT, 1, 8) BETWEEN P.DT_FROM8 AND P.DT_TO8 ) WHERE RN = 1 ) , USERS AS ( SELECT USER_KEY FROM CHK_TODAY UNION SELECT USER_KEY FROM LOGIN_TODAY UNION SELECT USER_KEY FROM BLK_TODAY UNION SELECT USER_KEY FROM ME_TODAY ) SELECT NVL(C.USER_ID, NVL(L.USER_ID, NVL(E.USER_ID, NVL(I.BLK_USER_ID, U.USER_KEY)))) AS USER_ID , NVL(C.TODAY_TOT , 0) AS TODAY_TOT , NVL(C.TODAY_EXC , 0) AS TODAY_EXC , NVL(C.TODAY_REAL, 0) AS TODAY_REAL , NVL(E.ME_TOT , 0) AS ME_TOT , NVL(E.ME_EXC , 0) AS ME_EXC , NVL(E.ME_TOT , 0) - NVL(E.ME_EXC, 0) AS ME_REAL , NVL(M.M5_TOT , 0) AS MIN5_TOT , NVL(M.M5_EXC , 0) AS MIN5_EXC , NVL(M.M5_REAL, 0) AS MIN5_REAL , NVL(L.LGN_TODAY_TOT , 0) AS LGN_TODAY_TOT , NVL(L.LGN_TODAY_SUCC, 0) AS LGN_TODAY_SUCC , NVL(L.LGN_TODAY_E1 , 0) AS LGN_TODAY_E1 , NVL(L.LGN_TODAY_E2 , 0) AS LGN_TODAY_E2 , NVL(L.LGN_TODAY_E3 , 0) AS LGN_TODAY_E3 , NVL(L.LGN_TODAY_E4 , 0) AS LGN_TODAY_E4 , NVL(L.LGN_TODAY_E5 , 0) AS LGN_TODAY_E5 , NVL(L.LGN_TODAY_ERR , 0) AS LGN_TODAY_ERR , NVL(LP.LGN_IP_CNT , 0) AS LGN_IP_CNT , NVL(L.LGN_5M_TOT , 0) AS LGN_MIN5_TOT , NVL(L.LGN_5M_SUCC, 0) AS LGN_MIN5_SUCC , NVL(L.LGN_5M_ERR , 0) AS LGN_MIN5_ERR , NVL(B.BLK_TODAY_CNT, 0) AS BLK_TODAY_CNT , NVL(T.BLK_10M_CNT , 0) AS BLK_MIN10_CNT , NVL(B.BLK_IP_CNT , 0) AS BLK_IP_CNT , NVL(C.CHK_LAST_IP, '-') AS CHK_LAST_IP , NVL(C.CHK_IP_CNT , 0) AS CHK_IP_CNT , NVL(P5.M5_IPS , '-') AS MIN5_IPS , CASE WHEN H.USER_KEY IS NOT NULL THEN 'Y' ELSE 'N' END AS IP_HIT , NVL(I.COUNTRY_CODE, '-') AS COUNTRY_CODE , NVL(I.REAL_IP, '-') AS BLK_REAL_IP , NVL(I.STAT_CD, '-') AS BLK_STAT_CD , NVL(I.LOGIN_ORGN, '-') AS BLK_LOGIN_ORGN , NVL(I.ORGN_CD, '-') AS BLK_ORGN_CD , NVL(I.V_USER_ID, '-') AS BLK_V_USER_ID , NVL(I.BLOCK_REASON, '-') AS BLOCK_REASON , NVL(TO_CHAR(TO_DATE(B.BLK_FIRST_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS'),'-') AS BLK_FIRST_F , NVL(TO_CHAR(TO_DATE(B.BLK_LAST_DT ,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS'),'-') AS BLK_LAST_F , NVL(C.CHK_FIRST_TS, '-') AS CHK_FIRST_TS , NVL(L.LGN_FIRST_TS, '-') AS LGN_FIRST_TS , NVL(C.CHK_LAST_TS, '-') AS CHK_LAST_TS , NVL(L.LGN_LAST_TS, '-') AS LGN_LAST_TS , NVL(C.WAS_CNT, 0) AS WAS_CNT , CASE WHEN H.USER_KEY IS NOT NULL AND NVL(M.M5_REAL, 0) > 0 THEN 'A' WHEN NVL(T.BLK_10M_CNT, 0) > 0 AND NVL(M.M5_REAL, 0) > 0 THEN 'B' WHEN NVL(T.BLK_10M_CNT, 0) > 0 THEN 'C' WHEN NVL(L.LGN_5M_ERR , 0) > 0 AND NVL(B.BLK_TODAY_CNT,0) > 0 THEN 'D' WHEN NVL(B.BLK_TODAY_CNT, 0) > 0 THEN 'E' WHEN NVL(L.LGN_5M_ERR , 0) > 0 THEN 'F' ELSE '-' END AS RISK FROM USERS U LEFT OUTER JOIN CHK_TODAY C ON C.USER_KEY = U.USER_KEY LEFT OUTER JOIN CHK_5M M ON M.USER_KEY = U.USER_KEY LEFT OUTER JOIN CHK_5M_IP P5 ON P5.USER_KEY = U.USER_KEY LEFT OUTER JOIN CHK_IP_HIT H ON H.USER_KEY = U.USER_KEY LEFT OUTER JOIN LOGIN_TODAY L ON L.USER_KEY = U.USER_KEY LEFT OUTER JOIN LIP_TODAY LP ON LP.USER_KEY = U.USER_KEY LEFT OUTER JOIN ME_TODAY E ON E.USER_KEY = U.USER_KEY LEFT OUTER JOIN BLK_TODAY B ON B.USER_KEY = U.USER_KEY LEFT OUTER JOIN BLK_10M T ON T.USER_KEY = U.USER_KEY LEFT OUTER JOIN BLK_INFO I ON I.USER_KEY = U.USER_KEY
WHERE UPPER(U.USER_KEY) LIKE '%'||UPPER(#{chkUserId})||'%'
OR NVL(C.TODAY_REAL , 0) >= #{thChkToday} OR NVL(M.M5_REAL , 0) >= #{thChk5m} OR NVL(B.BLK_TODAY_CNT, 0) >= #{thBlkToday} OR NVL(T.BLK_10M_CNT , 0) >= #{thBlk10m} OR NVL(L.LGN_TODAY_TOT, 0) >= #{thLgnToday} OR NVL(L.LGN_5M_TOT , 0) >= #{thLgn5m}
ORDER BY CASE WHEN H.USER_KEY IS NOT NULL THEN 0 WHEN NVL(T.BLK_10M_CNT, 0) > 0 THEN 1 WHEN NVL(B.BLK_TODAY_CNT, 0) > 0 THEN 2 ELSE 3 END , NVL(M.M5_REAL , 0) DESC , NVL(L.LGN_5M_TOT, 0) DESC , NVL(C.TODAY_REAL, 0) DESC , USER_ID

/* UserWebHistMapper.getUserStatFg */
SELECT  USER_STAT_FG
FROM    TB_WB_USER_INFO
WHERE   USER_ID = #{userId}

mapper.insert:
/* UserWebHistMapper.insertUserPauseHist */
INSERT INTO TB_WB_USER_PAUSE_HIST
(   PAUSE_SEQ,      USER_ID,        PROC_FG,        PROC_DT,        PROC_ID
,   BEF_STAT_FG,    AFT_STAT_FG,    RESULT_FG
,   CHK_DAY1,       CHK_DAY2,       RISK
,   TODAY_REAL,     TODAY_TOT,      MIN5_REAL,      ME_REAL
,   LGN_TODAY_TOT,  LGN_TODAY_ERR,  LGN_MIN5_ERR,   LGN_IP_CNT
,   BLK_TODAY_CNT,  BLK_MIN10_CNT,  CHK_LAST_IP,    CHK_IP_CNT,     IP_HIT
,   COUNTRY_CODE,   BLOCK_REASON,   SUMMARY_TXT,    REMARK
,   REG_DT,         REG_ID,         MOD_DT,         MOD_ID
)
VALUES
(   SEQ_TB_WB_USER_PAUSE_HIST.NEXTVAL, #{userId}, #{procFg}, #{procDt}, #{procId}
,   #{befStatFg},   #{aftStatFg},   #{resultFg}
,   #{chkDay1},     #{chkDay2},     #{risk}
,   #{todayReal},   #{todayTot},    #{min5Real},    #{meReal}
,   #{lgnTodayTot}, #{lgnTodayErr}, #{lgnMin5Err},  #{lgnIpCnt}
,   #{blkTodayCnt}, #{blkMin10Cnt}, #{chkLastIp},   #{chkIpCnt},    #{ipHit}
,   #{countryCode}, #{blockReason}, #{summaryTxt},  #{remark}
,   #{regDt},       #{regId},       #{modDt},       #{modId}
)

mapper.select:
/* UserWebHistMapper.getUserPauseHistList */ SELECT H.PAUSE_SEQ , H.USER_ID , H.PROC_FG , CASE H.PROC_FG WHEN 'P' THEN '일시정지' WHEN 'R' THEN '해제' ELSE H.PROC_FG END AS PROC_FG_NM , TO_CHAR(TO_DATE(H.PROC_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS PROC_DT , H.PROC_ID , H.BEF_STAT_FG , H.AFT_STAT_FG , H.RESULT_FG , CASE WHEN H.CHK_DAY1 = H.CHK_DAY2 THEN TO_CHAR(TO_DATE(H.CHK_DAY1,'YYYYMMDD'),'YYYY-MM-DD') ELSE TO_CHAR(TO_DATE(H.CHK_DAY1,'YYYYMMDD'),'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(H.CHK_DAY2,'YYYYMMDD'),'YYYY-MM-DD') END AS CHK_PERIOD , H.RISK , H.TODAY_REAL , H.MIN5_REAL , H.ME_REAL , H.LGN_TODAY_TOT , H.LGN_TODAY_ERR , H.LGN_IP_CNT , H.BLK_TODAY_CNT , H.BLK_MIN10_CNT , H.CHK_LAST_IP , H.IP_HIT , H.COUNTRY_CODE , H.SUMMARY_TXT , H.REMARK FROM TB_WB_USER_PAUSE_HIST H WHERE 1 = 1 AND H.PROC_DT BETWEEN #{chkDay1} || '000000' AND #{chkDay2} || '235959'
AND UPPER(H.USER_ID) = UPPER(#{userId})
ORDER BY H.PROC_DT DESC, H.PAUSE_SEQ DESC
